const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const shebelleRiver = ee.Geometry.Point(45.34, 2.21).buffer(5000); // 5km buffer around a point on Shebelle River

  const date1_start = '2018-05-01';
  const date1_end = '2018-05-15'; // Centered around May 9, 2018

  const date2_start = '2015-05-10';
  const date2_end = '2015-05-24'; // Centered around May 17, 2015

  const S1_COLLECTION = 'COPERNICUS/S1_GRD';
  const SCALE = 100; // Resolution for analysis (m)
  const WATER_THRESHOLD_VV = -18; // dB, common threshold for water detection using VV polarization

  // Function to get Sentinel-1 data and create a water mask
  const getWaterArea = (startDate, endDate, geometry) => {
    let collection = ee.ImageCollection(S1_COLLECTION)
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'));

    if (collection.size().getInfo() === 0) {
      return { area: null, count: 0, image_count: 0 }; // Indicate no images
    }

    const image = collection.median(); // Use median to reduce speckle and get a representative image

    // If the image is still null after median, something is wrong
    if (!image) {
        return { area: null, count: 0, image_count: collection.size().getInfo() };
    }

    // Convert to dB and create a water mask
    const vv = image.select('VV').focal_median(3); // Apply focal median to smooth
    const waterMask = vv.lt(WATER_THRESHOLD_VV).rename('water');

    // Calculate water area
    const waterArea = waterMask.multiply(ee.Image.pixelArea()).divide(1e6); // Area in km^2

    // Reduce the water area to get the total sum within the geometry
    const stats = waterArea.reduceRegion({
      reducer: ee.Reducer.sum().unweighted(), // unweighted so it sums exactly the pixel areas
      geometry: geometry,
      scale: SCALE,
      maxPixels: 1e9
    });

    const area = stats.get('water').getInfo();
    const pixelCount = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: SCALE,
      maxPixels: 1e9
    }).get('water').getInfo();

    return { area: area, count: pixelCount, image_count: collection.size().getInfo() };
  };

  // 2. Data Acquisition & Check for 2018
  console.log(`--- Period 2018 (${date1_start} to ${date1_end}) ---`);
  const result2018 = getWaterArea(date1_start, date1_end, shebelleRiver);

  if (result2018.image_count === 0) {
    console.log("No Sentinel-1 images found for 2018 period.");
    console.log("C1");
    return;
  }
  if (result2018.count === 0 && result2018.area === 0) { // If no water pixels are found, but images exist, it's a valid zero, not C2 here.
    console.log("No valid pixels detected as water in 2018 after processing.");
    // This is a valid observation that there might not be water, not a processing failure.
  }
  if (result2018.area === null) {
      console.log("Calculation failed for 2018 (area is null).");
      console.log("C3");
      return;
  }
  const waterArea2018 = result2018.area;
  console.log(`2018 Images: ${result2018.image_count}, Water Pixels: ${result2018.count}, Water Area: ${waterArea2018 ? waterArea2018.toFixed(2) : 'N/A'} km^2`);

  // 3. Data Acquisition & Check for 2015
  console.log(`--- Period 2015 (${date2_start} to ${date2_end}) ---`);
  const result2015 = getWaterArea(date2_start, date2_end, shebelleRiver);

  if (result2015.image_count === 0) {
    console.log("No Sentinel-1 images found for 2015 period.");
    console.log("C1");
    return;
  }
  if (result2015.count === 0 && result2015.area === 0) {
    console.log("No valid pixels detected as water in 2015 after processing.");
  }
  if (result2015.area === null) {
      console.log("Calculation failed for 2015 (area is null).");
      console.log("C3");
      return;
  }
  const waterArea2015 = result2015.area;
  console.log(`2015 Images: ${result2015.image_count}, Water Pixels: ${result2015.count}, Water Area: ${waterArea2015 ? waterArea2015.toFixed(2) : 'N/A'} km^2`);

  // 4. Comparison and Final Answer
  if (waterArea2018 === null || waterArea2015 === null) {
    console.log("C3"); // Should be caught by earlier checks, but a final fail-safe
    return;
  }

  console.log("\nComparison:");
  if (waterArea2018 > waterArea2015) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
